defined('ABSPATH') || exit;

function wutm_hp_defaults(): array {
    return ['width'=>'100%','columns'=>4,'rows'=>3,'product_type'=>'recent','category'=>'','product_ids'=>'','autoplay'=>1,'speed'=>5,'middle_content'=>'','show_cart'=>1,'show_more'=>1,'more_url'=>'/shop/','more_text'=>'查看更多','accent'=>'#111111','button_text'=>'#ffffff','slides'=>[]];
}
function wutm_hp_options(): array { return wp_parse_args((array) get_option('wutm_homepage_products', []), wutm_hp_defaults()); }
function wutm_hp_css_size($value, string $fallback): string { $value = trim((string) $value); return preg_match('/^\d+(?:\.\d+)?(?:px|%|vw|rem|em)$/', $value) ? $value : $fallback; }
function wutm_hp_sanitize($input): array {
    $input = is_array($input) ? $input : [];
    $types = ['recent','featured','sale','best_selling','category','specific'];
    $clean = [
        'width'=>wutm_hp_css_size($input['width'] ?? '', '100%'), 'columns'=>max(1,min(6,absint($input['columns'] ?? 4))), 'rows'=>max(1,min(20,absint($input['rows'] ?? 3))),
        'product_type'=>in_array($input['product_type'] ?? '', $types, true) ? $input['product_type'] : 'recent', 'category'=>sanitize_title($input['category'] ?? ''),
        'product_ids'=>implode(',', array_filter(array_map('absint', preg_split('/\s*,\s*/', (string) ($input['product_ids'] ?? ''))))), 'autoplay'=>empty($input['autoplay'])?0:1,
        'speed'=>max(2,min(30,absint($input['speed'] ?? 5))), 'middle_content'=>wp_kses_post($input['middle_content'] ?? ''), 'show_cart'=>empty($input['show_cart'])?0:1,
        'show_more'=>empty($input['show_more'])?0:1, 'more_url'=>esc_url_raw($input['more_url'] ?? '/shop/'), 'more_text'=>sanitize_text_field($input['more_text'] ?? '查看更多'),
        'accent'=>sanitize_hex_color($input['accent'] ?? '') ?: '#111111', 'button_text'=>sanitize_hex_color($input['button_text'] ?? '') ?: '#ffffff', 'slides'=>[],
    ];
    foreach ((array) ($input['slides'] ?? []) as $slide) {
        $desktop = esc_url_raw($slide['desktop'] ?? ''); if ($desktop === '') continue;
        $clean['slides'][] = ['desktop'=>$desktop,'mobile'=>esc_url_raw($slide['mobile'] ?? ''),'link'=>esc_url_raw($slide['link'] ?? '')];
        if (count($clean['slides']) >= 10) break;
    }
    return $clean;
}
add_action('admin_init', function () { register_setting('wutm_hp_group','wutm_homepage_products',['type'=>'array','sanitize_callback'=>'wutm_hp_sanitize','default'=>wutm_hp_defaults()]); });
