function wutm_hp_slide_row(int $i,array $s){?><div class="wutm-hp-slide"><button type="button" class="button wutm-hp-remove">刪除</button><h3>輪播圖片</h3><div class="wutm-hp-field">電腦版圖片<div class="wutm-hp-slide-grid"><input name="wutm_homepage_products[slides][<?php echo $i;?>][desktop]" value="<?php echo esc_attr($s['desktop']??'');?>"><button type="button" class="button wutm-hp-upload">媒體庫</button></div></div><div class="wutm-hp-field">手機版圖片（選填）<div class="wutm-hp-slide-grid"><input name="wutm_homepage_products[slides][<?php echo $i;?>][mobile]" value="<?php echo esc_attr($s['mobile']??'');?>"><button type="button" class="button wutm-hp-upload">媒體庫</button></div></div><div class="wutm-hp-field">連結（選填）<input type="url" name="wutm_homepage_products[slides][<?php echo $i;?>][link]" value="<?php echo esc_attr($s['link']??'');?>"></div></div><?php }

function wutm_hp_shortcode($atts):string{
    $o=wutm_hp_options();$atts=shortcode_atts(['columns'=>$o['columns'],'rows'=>$o['rows'],'width'=>$o['width']],$atts,'wutm_home_products');$cols=max(1,min(6,absint($atts['columns'])));$rows=max(1,min(20,absint($atts['rows'])));$limit=$cols*$rows;$width=wutm_hp_css_size($atts['width'],'100%');
    $args=['limit'=>$limit,'columns'=>$cols,'orderby'=>'date','order'=>'DESC'];switch($o['product_type']){case'featured':$args['visibility']='featured';break;case'sale':$args['on_sale']='true';break;case'best_selling':$args['best_selling']='true';break;case'category':$args['category']=$o['category'];break;case'specific':$args['ids']=$o['product_ids'];$args['orderby']='post__in';break;}
    $pairs=[];foreach($args as $k=>$v){if($v!==''&&$v!==false)$pairs[]=$k.'="'.esc_attr((string)$v).'"';}$products=do_shortcode('[products '.implode(' ',$pairs).']');$uid=wp_unique_id('wutm-hp-');ob_start();?><div id="<?php echo esc_attr($uid);?>" class="wutm-home-products" style="--wutm-hp-width:<?php echo esc_attr($width);?>;--wutm-hp-cols:<?php echo $cols;?>;--wutm-hp-accent:<?php echo esc_attr($o['accent']);?>"><?php if($o['slides']):?><div class="wutm-hp-slider" data-speed="<?php echo max(2000,(int)$o['speed']*1000);?>" data-autoplay="<?php echo (int)$o['autoplay'];?>"><?php foreach($o['slides'] as $i=>$s):?><div class="wutm-hp-frame<?php echo $i===0?' is-active':'';?>"><?php if($s['link']):?><a href="<?php echo esc_url($s['link']);?>"><?php endif;?><picture><?php if($s['mobile']):?><source media="(max-width:767px)" srcset="<?php echo esc_url($s['mobile']);?>"><?php endif;?><img src="<?php echo esc_url($s['desktop']);?>" alt="" <?php echo $i?'loading="lazy"':'';?>></picture><?php if($s['link']):?></a><?php endif;?></div><?php endforeach;?><?php if(count($o['slides'])>1):?><button type="button" class="wutm-hp-prev" aria-label="上一張">‹</button><button type="button" class="wutm-hp-next" aria-label="下一張">›</button><?php endif;?></div><?php endif;?><?php if(trim(wp_strip_all_tags($o['middle_content']))!==''):?><div class="wutm-hp-middle"><?php echo do_shortcode(wpautop(wp_kses_post($o['middle_content'])));?></div><?php endif;?><div class="wutm-hp-products<?php echo $o['show_cart']?'':' hide-cart';?>"><?php echo $products;?></div><?php if($o['show_more']&&$o['more_url']):?><p class="wutm-hp-more"><a href="<?php echo esc_url($o['more_url']);?>"><?php echo esc_html($o['more_text']);?></a></p><?php endif;?></div><style>#<?php echo esc_attr($uid);?>{width:100%;max-width:var(--wutm-hp-width);margin:auto;padding:0 15px;box-sizing:border-box}#<?php echo esc_attr($uid);?> .wutm-hp-slider{position:relative;display:grid;grid-template-areas:"slide";overflow:hidden;border-radius:12px;margin-bottom:28px;background:#f4f5f7}#<?php echo esc_attr($uid);?> .wutm-hp-frame{grid-area:slide;opacity:0;visibility:hidden;transition:opacity .65s}#<?php echo esc_attr($uid);?> .wutm-hp-frame.is-active{opacity:1;visibility:visible}#<?php echo esc_attr($uid);?> .wutm-hp-frame img{display:block;width:100%;height:auto}#<?php echo esc_attr($uid);?> .wutm-hp-prev,#<?php echo esc_attr($uid);?> .wutm-hp-next{position:absolute;z-index:2;top:50%;width:42px;height:42px;border:0;border-radius:50%;background:#0008;color:#fff;font-size:28px;transform:translateY(-50%);cursor:pointer}#<?php echo esc_attr($uid);?> .wutm-hp-prev{left:14px}#<?php echo esc_attr($uid);?> .wutm-hp-next{right:14px}#<?php echo esc_attr($uid);?> .wutm-hp-middle{margin:28px 0}#<?php echo esc_attr($uid);?> .products{display:grid!important;grid-template-columns:repeat(var(--wutm-hp-cols),minmax(0,1fr))!important;gap:20px!important}#<?php echo esc_attr($uid);?> .products .product{width:auto!important;margin:0!important}#<?php echo esc_attr($uid);?> .hide-cart .add_to_cart_button,#<?php echo esc_attr($uid);?> .hide-cart .ct-cart-actions{display:none!important}#<?php echo esc_attr($uid);?> .wutm-hp-more{text-align:center;margin:35px 0}#<?php echo esc_attr($uid);?> .wutm-hp-more a{display:inline-block;padding:12px 28px;border-radius:8px;background:var(--wutm-hp-accent);color:#fff;text-decoration:none}@media(max-width:900px){#<?php echo esc_attr($uid);?> .products{grid-template-columns:repeat(2,minmax(0,1fr))!important}}</style><script>(function(){const r=document.getElementById(<?php echo wp_json_encode($uid);?>),s=r&&r.querySelector('.wutm-hp-slider');if(!s)return;const a=[...s.querySelectorAll('.wutm-hp-frame')];if(a.length<2)return;let i=0,t;function show(n){a[i].classList.remove('is-active');i=(n+a.length)%a.length;a[i].classList.add('is-active')}function start(){if(s.dataset.autoplay==='1'&&!t)t=setInterval(()=>show(i+1),parseInt(s.dataset.speed,10)||5000)}s.querySelector('.wutm-hp-next').onclick=()=>{show(i+1);clearInterval(t);t=null;start()};s.querySelector('.wutm-hp-prev').onclick=()=>{show(i-1);clearInterval(t);t=null;start()};s.addEventListener('mouseenter',()=>{clearInterval(t);t=null});s.addEventListener('mouseleave',start);start()})();</script><?php return ob_get_clean();
}
